func TestEnumListArticlesRequestMedia(t *testing.T) {
	t.Run("NewFromString_all", func(t *testing.T) {
		t.Parallel()
		val, err := NewListArticlesRequestMediaFromString("all")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ListArticlesRequestMedia("all"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_none", func(t *testing.T) {
		t.Parallel()
		val, err := NewListArticlesRequestMediaFromString("none")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ListArticlesRequestMedia("none"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewListArticlesRequestMediaFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewListArticlesRequestMediaFromString("all")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
